/* yuexin_cat_angry.c - REAL 149-frame YuexinCat angry animation.
 * Source of the frames: the user's uploaded reference player
 * (firmware/references/angry/YuexinCat_STM32F103C8T6_single_file.c), which
 * stores 149 monochrome 64x64 frames extracted from the original 30 fps MP4
 * as an LZSS stream. Those frames were decoded and re-packed here into the
 * project's XOR + Elias-gamma delta format so animation.c plays them with the
 * exact decoder already used by the dance stage - same character, same motion.
 * Frames: 149 x 64x64, 30 fps (33/33/34 ms), ping-pong loop.
 * Payload: frame0 512 B + offsets 300 B + counts 298 B + stream 37882 B.
 * counts[] are uint16_t and YcatVideoAsset.countsWide is 1, because 64x64
 * frames change more than 255 bytes per frame.
 * Encoder round-trip verified frame-by-frame against the firmware decoder.
 */
